# driver
# --------------------------------------------------------------------------
def handle_line(raw):
    if len(raw) > LINE_BYTES:
        return ERR_LIMIT
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return ERR_JSON
    if depth_exceeded(text):
        return ERR_LIMIT
    try:
        obj = parse_json(text)
    except ValueError:
        return ERR_JSON
    except RecursionError:
        return ERR_JSON
    try:
        info = validate(obj)
    except SchemaErr:
        return ERR_SCHEMA
    except LimitErr:
        return ERR_LIMIT
    try:
        result = compile_request(info)
    except ComplexErr:
        return ERR_COMPLEXITY
    except (SchemaErr, LimitErr):
        return ERR_SCHEMA
    except RecursionError:
        return ERR_LIMIT
    return json.dumps(result, separators=(',', ':')).encode('utf-8') + b'\n'


def main():
    data = sys.stdin.buffer.read()
    out = sys.stdout.buffer
    if data:
        lines = data.split(b'\n')
        if lines[-1] == b'':
            lines.pop()
        for raw in lines:
            try:
                payload = handle_line(raw)
            except Exception:                      # pragma: no cover
                payload = ERR_JSON
            out.write(payload)
    out.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())
